files.content:
body {
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  background: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
  min-block-size: 100dvh;
}

.wrapper {
  max-inline-size: 850px;
}

p {
  margin: 40px;
  color: #fff;
  font-weight: bold;
  font-size: 6em;
}

.stroke {
  color: transparent;
}

@supports ((text-stroke: 1px #000) or (-webkit-text-stroke: 1px #000)) {
  .stroke {
    -webkit-text-stroke: 2px #000;
    text-stroke: 2px #000;
  }
}
